use rustler::types::atom::Atom;


use rustler::{Binary, Encoder, Env, Error, NifResult, Term};


use std::sync::OnceLock;


use crate::runtime::Decoder;


/// The atom for a schema name, interned once per process. Atoms are never freed, so a cached
/// atom stays valid across calls and threads; the names are static, so their address and length
/// identify them without hashing their text. Each scheduler thread keeps its own copy of the
/// atoms it has used, so a lookup takes no lock once that thread has seen the name.
fn kiwi_atom(env: Env<'_>, name: &'static str) -> Atom {
    type KiwiAtoms = std::collections::HashMap<(usize, usize), Atom, KiwiAtomHasher>;

    static SHARED: std::sync::OnceLock<std::sync::RwLock<KiwiAtoms>> = std::sync::OnceLock::new();

    thread_local! {
        static LOCAL: std::cell::RefCell<KiwiAtoms> = std::cell::RefCell::new(KiwiAtoms::default());
    }

    let key = (name.as_ptr() as usize, name.len());

    LOCAL.with(|local| {
        *local.borrow_mut().entry(key).or_insert_with(|| {
            let shared = SHARED.get_or_init(Default::default);
            let known = shared.read().ok().and_then(|atoms| atoms.get(&key).copied());

            known.unwrap_or_else(|| {
                let atom = Atom::from_str(env, name).unwrap();
                if let Ok(mut atoms) = shared.write() {
                    atoms.insert(key, atom);
                }
                atom
            })
        })
    })
}

/// Mixes a static name's address and length; the keys need no protection from collisions.
#[derive(Default)]
struct KiwiAtomHash(u64);

impl std::hash::Hasher for KiwiAtomHash {
    fn finish(&self) -> u64 {
        self.0
    }

    fn write(&mut self, bytes: &[u8]) {
        for byte in bytes {
            self.write_u64(u64::from(*byte));
        }
    }

    fn write_usize(&mut self, value: usize) {
        self.write_u64(value as u64);
    }

    fn write_u64(&mut self, value: u64) {
        self.0 = (self.0.rotate_left(5) ^ value).wrapping_mul(0x51_7c_c1_b7_27_22_0a_95);
    }
}

type KiwiAtomHasher = std::hash::BuildHasherDefault<KiwiAtomHash>;

pub type KiwiDecodeFn = for<'a> fn(Env<'a>, &mut Decoder<'_>) -> NifResult<Term<'a>>;


#[derive(Clone, Debug)]
pub struct KiwiEnumVariant {
    pub value: u32,
    pub name: &'static str,
}


macro_rules! kiwi_enum_decoder {
        (fn $name:ident;
        variants [$($variant_value:literal, $variant_name:literal;)*]) => {
                fn $name<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
                        kiwi_enum_value(env, decoder, &[$(KiwiEnumVariant { value: $variant_value, name: $variant_name },)*])
                }
        };
}

fn kiwi_bool_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    Ok(decoder.read_bool()?.encode(env))
}


fn kiwi_byte_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    Ok(decoder.read_byte()?.encode(env))
}


fn kiwi_int_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    Ok(decoder.read_var_int()?.encode(env))
}


fn kiwi_uint_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    Ok(decoder.read_var_uint()?.encode(env))
}


fn kiwi_float_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    decoder.read_var_float(env)
}


fn kiwi_string_value<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    decoder.read_string(env)
}


fn kiwi_int64_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    Ok(decoder.read_var_int64()?.encode(env))
}


fn kiwi_uint64_value<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    Ok(decoder.read_var_uint64()?.encode(env))
}


fn kiwi_bytes_value<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
    decoder.read_byte_array(env)
}


fn kiwi_enum_value<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
    variants: &[KiwiEnumVariant],
) -> NifResult<Term<'a>> {
    let value = decoder.read_var_uint()?;
    match variants.binary_search_by_key(&value, |variant| variant.value) {
        Ok(index) => Ok(kiwi_atom(env, variants[index].name).encode(env)),
        Err(_index) => Ok(value.encode(env)),
    }
}


fn kiwi_field_value<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
    repeated: bool,
    decode: KiwiDecodeFn,
) -> NifResult<Term<'a>> {
    if repeated {
        Ok(decoder.read_repeated(|decoder| decode(env, decoder))?.encode(env))
    } else {
        decode(env, decoder)
    }
}


#[derive(Clone, Debug)]
pub struct KiwiSparseField {
    pub id: u32,
    pub name: &'static str,
    pub repeated: bool,
    pub decode: KiwiDecodeFn,
}


macro_rules! kiwi_sparse_struct_decoder {
        (fn $name:ident;
        module $module_name:literal;
        fields [$($field_id:literal, $field_name:literal, $field_repeated:literal, $field_decode:ident;)*]) => {
                fn $name<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
                        kiwi_sparse_struct_fields(env, decoder, $module_name, &[$(KiwiSparseField { id: $field_id, name: $field_name, repeated: $field_repeated, decode: $field_decode },)*])
                }
        };
}

fn kiwi_sparse_struct_fields<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
    module_name: &'static str,
    fields: &[KiwiSparseField],
) -> NifResult<Term<'a>> {
    let mut keys = Vec::with_capacity(fields.len() + 1);
    let mut values = Vec::with_capacity(fields.len() + 1);
    kiwi_sparse_module_entry(env, module_name, &mut keys, &mut values);
    for field in fields {
        keys.push(kiwi_atom(env, field.name).encode(env));
        values.push(kiwi_field_value(env, decoder, field.repeated, field.decode)?);
    }
    Term::map_from_term_arrays(env, &keys, &values)
}


fn kiwi_sparse_message_fields<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
    module_name: &'static str,
    definition_name: &str,
    fields: &[KiwiSparseField],
) -> NifResult<Term<'a>> {
    let mut keys = Vec::with_capacity(fields.len() + 1);
    let mut values = Vec::with_capacity(fields.len() + 1);
    kiwi_sparse_module_entry(env, module_name, &mut keys, &mut values);
    kiwi_sparse_message_fields_remaining(
        env,
        decoder,
        definition_name,
        fields,
        &mut keys,
        &mut values,
    )?;
    Term::map_from_term_arrays(env, &keys, &values)
}


fn kiwi_sparse_message_fields_remaining<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
    definition_name: &str,
    fields: &[KiwiSparseField],
    keys: &mut Vec<Term<'a>>,
    values: &mut Vec<Term<'a>>,
) -> NifResult<()> {
    let field_id = decoder.read_var_uint()?;
    if field_id == 0 {
        Ok(())
    } else {
        match fields.binary_search_by_key(&field_id, |field| field.id) {
            Ok(index) => {
                let field = &fields[index];
                keys.push(kiwi_atom(env, field.name).encode(env));
                values
                    .push(kiwi_field_value(env, decoder, field.repeated, field.decode)?);
            }
            Err(_index) => {
                kiwi_unknown_field(decoder, definition_name, field_id)?;
            }
        };
        kiwi_sparse_message_fields_remaining(
            env,
            decoder,
            definition_name,
            fields,
            keys,
            values,
        )
    }
}


fn kiwi_sparse_module_entry<'a>(
    env: Env<'a>,
    module_name: &'static str,
    keys: &mut Vec<Term<'a>>,
    values: &mut Vec<Term<'a>>,
) {
    keys.push(kiwi_atom(env, "__kiwi_module__").encode(env));
    values.push(kiwi_atom(env, module_name).encode(env));
}


#[derive(Clone, Debug)]
pub struct KiwiSkipField {
    pub id: u32,
    pub kind: KiwiSkipKind,
}


pub type KiwiSkipFn = fn(&mut Decoder<'_>) -> NifResult<()>;


#[derive(Clone, Debug)]
pub enum KiwiSkipKind {
    One(KiwiSkipFn),
    Repeated(KiwiSkipFn),
    Bytes,
}


macro_rules! kiwi_skip_struct_decoder {
        (fn $name:ident;
        fields [$($field_repeated:literal, $field_bytes:literal, $field_skip:ident;)*]) => {
                fn $name(decoder: &mut Decoder<'_>) -> NifResult<()> {
                        kiwi_skip_struct_fields(decoder, &[$(kiwi_skip_descriptor_kind($field_repeated, $field_bytes, $field_skip),)*])
                }
        };
}

fn kiwi_skip_bool_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_bool()?;
    Ok(())
}


fn kiwi_skip_byte_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_byte()?;
    Ok(())
}


fn kiwi_skip_int_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_var_int()?;
    Ok(())
}


fn kiwi_skip_uint_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_var_uint()?;
    Ok(())
}


fn kiwi_skip_float_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_var_float_value()?;
    Ok(())
}


fn kiwi_skip_string_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.skip_string()?;
    Ok(())
}


fn kiwi_skip_int64_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_var_int64()?;
    Ok(())
}


fn kiwi_skip_uint64_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.read_var_uint64()?;
    Ok(())
}


fn kiwi_skip_bytes_value(decoder: &mut Decoder<'_>) -> NifResult<()> {
    decoder.skip_byte_array()?;
    Ok(())
}


fn kiwi_skip_descriptor_kind(
    repeated: bool,
    bytes: bool,
    skip: KiwiSkipFn,
) -> KiwiSkipKind {
    if bytes {
        KiwiSkipKind::Bytes
    } else if repeated {
        KiwiSkipKind::Repeated(skip)
    } else {
        KiwiSkipKind::One(skip)
    }
}


fn kiwi_skip_repeated(decoder: &mut Decoder<'_>, item: KiwiSkipFn) -> NifResult<()> {
    decoder.read_repeated(|decoder| item(decoder))?;
    Ok(())
}


fn kiwi_skip_kind(decoder: &mut Decoder<'_>, kind: &KiwiSkipKind) -> NifResult<()> {
    match kind {
        KiwiSkipKind::One(skip) => skip(decoder),
        KiwiSkipKind::Repeated(skip) => kiwi_skip_repeated(decoder, *skip),
        KiwiSkipKind::Bytes => kiwi_skip_bytes_value(decoder),
    }
}


fn kiwi_skip_struct_fields(
    decoder: &mut Decoder<'_>,
    fields: &[KiwiSkipKind],
) -> NifResult<()> {
    for kind in fields {
        kiwi_skip_kind(decoder, kind)?;
    }
    Ok(())
}


fn kiwi_skip_message_fields(
    decoder: &mut Decoder<'_>,
    definition_name: &str,
    fields: &[KiwiSkipField],
) -> NifResult<()> {
    let field_id = decoder.read_var_uint()?;
    if field_id == 0 {
        Ok(())
    } else {
        match fields.binary_search_by_key(&field_id, |field| field.id) {
            Ok(index) => {
                kiwi_skip_kind(decoder, &fields[index].kind)?;
            }
            Err(_index) => {
                kiwi_unknown_field(decoder, definition_name, field_id)?;
            }
        };
        kiwi_skip_message_fields(decoder, definition_name, fields)
    }
}


macro_rules! kiwi_sparse_skip_message_decoder {
        (sparse_fn $sparse_name:ident;
        skip_fn $skip_name:ident;
        module $module_name:literal;
        definition $definition_name:literal;
        fields [$($field_id:literal, $field_name:literal, $field_repeated:literal, $field_decode:ident, $field_skip_repeated:literal, $field_skip_bytes:literal, $field_skip:ident;)*]) => {
                fn $sparse_name<'a>(env: Env<'a>, decoder: &mut Decoder<'_>) -> NifResult<Term<'a>> {
                        kiwi_sparse_message_fields(env, decoder, $module_name, $definition_name, &[$(KiwiSparseField { id: $field_id, name: $field_name, repeated: $field_repeated, decode: $field_decode },)*])
                }
                
                fn $skip_name(decoder: &mut Decoder<'_>) -> NifResult<()> {
                        kiwi_skip_message_fields(decoder, $definition_name, &[$(KiwiSkipField { id: $field_id, kind: kiwi_skip_descriptor_kind($field_skip_repeated, $field_skip_bytes, $field_skip) },)*])
                }
        };
}

/// A binary Kiwi schema read at runtime.
///
/// Encoded Kiwi data is not self-describing, so a decoder compiled from one schema
/// cannot step over a message field added by a newer one. Files usually carry the
/// schema they were written with; this keeps the types it declares so compiled
/// decoders can skip fields they do not know instead of rejecting the data.
pub struct KiwiRuntimeSchema {
    definitions: Vec<KiwiRuntimeDefinition>,
    by_name: std::collections::HashMap<String, usize>,
}

struct KiwiRuntimeDefinition {
    kind: u8,
    /// Struct fields in wire order; message fields sorted by id.
    fields: Vec<KiwiRuntimeField>,
}

#[derive(Clone, Copy)]
struct KiwiRuntimeField {
    id: u32,
    /// Bitwise-negated primitive index when negative, otherwise a definition index.
    type_index: i32,
    array: bool,
}

const KIWI_RUNTIME_ENUM: u8 = 0;
const KIWI_RUNTIME_STRUCT: u8 = 1;
const KIWI_RUNTIME_MESSAGE: u8 = 2;
const KIWI_RUNTIME_PRIMITIVES: i32 = 8;
const KIWI_RUNTIME_BYTE: i32 = !1;
const KIWI_RUNTIME_MAX_DEPTH: usize = 512;

impl KiwiRuntimeSchema {
    /// Reads a schema in Kiwi's compact binary format.
    pub fn decode(bytes: &[u8]) -> NifResult<Self> {
        let mut decoder = Decoder::new(bytes);
        let count = decoder.read_var_uint()? as usize;
        let mut definitions = Vec::with_capacity(count.min(bytes.len()));
        let mut by_name = std::collections::HashMap::with_capacity(count.min(bytes.len()));

        for index in 0..count {
            let name = decoder.read_string_value()?;
            let kind = decoder.read_byte()?;
            if kind > KIWI_RUNTIME_MESSAGE {
                return Err(Error::BadArg);
            }

            let field_count = decoder.read_var_uint()? as usize;
            let mut fields = Vec::with_capacity(field_count.min(bytes.len()));
            for _ in 0..field_count {
                decoder.skip_string()?;
                let type_index = decoder.read_var_int()?;
                let array = decoder.read_byte()? != 0;
                let id = decoder.read_var_uint()?;
                fields.push(KiwiRuntimeField { id, type_index, array });
            }

            if kind == KIWI_RUNTIME_MESSAGE {
                fields.sort_by_key(|field| field.id);
            }

            definitions.push(KiwiRuntimeDefinition { kind, fields });
            by_name.insert(name, index);
        }

        decoder.finish()?;

        let valid_type = |type_index: i32| {
            (type_index < 0 && !type_index < KIWI_RUNTIME_PRIMITIVES)
                || (type_index >= 0 && (type_index as usize) < definitions.len())
        };

        let valid = definitions
            .iter()
            .filter(|definition| definition.kind != KIWI_RUNTIME_ENUM)
            .flat_map(|definition| definition.fields.iter())
            .all(|field| valid_type(field.type_index));

        if valid {
            Ok(Self { definitions, by_name })
        } else {
            Err(Error::BadArg)
        }
    }

    /// Skips the value of `field` in the message named `definition`.
    pub fn skip_field(&self, decoder: &mut Decoder<'_>, definition: &str, field: u32) -> NifResult<()> {
        let index = *self.by_name.get(definition).ok_or(Error::BadArg)?;
        let field = self.message_field(index, field)?;
        self.skip_value(decoder, field, 0)
    }

    fn message_field(&self, definition: usize, id: u32) -> NifResult<KiwiRuntimeField> {
        let fields = &self.definitions[definition].fields;
        fields
            .binary_search_by_key(&id, |field| field.id)
            .map(|index| fields[index])
            .map_err(|_| Error::BadArg)
    }

    fn skip_value(&self, decoder: &mut Decoder<'_>, field: KiwiRuntimeField, depth: usize) -> NifResult<()> {
        if !field.array {
            return self.skip_one(decoder, field.type_index, depth);
        }

        if field.type_index == KIWI_RUNTIME_BYTE {
            return decoder.skip_byte_array();
        }

        let count = decoder.read_var_uint()?;
        for _ in 0..count {
            self.skip_one(decoder, field.type_index, depth)?;
        }
        Ok(())
    }

    fn skip_one(&self, decoder: &mut Decoder<'_>, type_index: i32, depth: usize) -> NifResult<()> {
        if depth > KIWI_RUNTIME_MAX_DEPTH {
            return Err(Error::BadArg);
        }

        if type_index < 0 {
            return match !type_index {
                0 => decoder.read_bool().map(|_| ()),
                1 => decoder.read_byte().map(|_| ()),
                2 => decoder.read_var_int().map(|_| ()),
                3 => decoder.read_var_uint().map(|_| ()),
                4 => decoder.read_var_float_value().map(|_| ()),
                5 => decoder.skip_string(),
                6 => decoder.read_var_int64().map(|_| ()),
                _ => decoder.read_var_uint64().map(|_| ()),
            };
        }

        let index = type_index as usize;
        match self.definitions[index].kind {
            KIWI_RUNTIME_ENUM => decoder.read_var_uint().map(|_| ()),
            KIWI_RUNTIME_STRUCT => {
                for field in &self.definitions[index].fields {
                    self.skip_value(decoder, *field, depth + 1)?;
                }
                Ok(())
            }
            _ => loop {
                match decoder.read_var_uint()? {
                    0 => return Ok(()),
                    id => {
                        let field = self.message_field(index, id)?;
                        self.skip_value(decoder, field, depth + 1)?;
                    }
                }
            },
        }
    }
}

/// Skips a message field the compiled schema does not define, using the schema the
/// decoder was given for the data. Without one, the field is rejected.
fn kiwi_unknown_field(decoder: &mut Decoder<'_>, definition: &str, field: u32) -> NifResult<()> {
    match decoder.runtime_schema() {
        Some(schema) => schema.skip_field(decoder, definition, field),
        None => Err(Error::BadArg),
    }
}

fn cached_atom(env: Env, cell: &OnceLock<Atom>, name: &str) -> Atom {
    *cell.get_or_init(|| Atom::from_str(env, name).unwrap())
}


fn cached_struct_keys(
    env: Env<'_>,
    cache: &'static OnceLock<Vec<Atom>>,
    fields: &[&str],
) -> &'static [Atom] {
    cache
        .get_or_init(|| {
            let mut keys = Vec::with_capacity(fields.len() + 1);
            keys.push(Atom::from_str(env, "__struct__").unwrap());
            for field in fields {
                keys.push(Atom::from_str(env, field).unwrap());
            }
            keys
        })
}


fn default_struct_values<'a>(env: Env<'a>, module: Atom, len: usize) -> Vec<Term<'a>> {
    let mut values = Vec::with_capacity(len + 1);
    values.resize(len + 1, Atom::from_str(env, "nil").unwrap().to_term(env));
    values[0] = module.to_term(env);
    values
}


fn make_struct_from_arrays<'a>(
    env: Env<'a>,
    keys: &[Atom],
    values: &[Term<'a>],
) -> NifResult<Term<'a>> {
    let key_terms = keys.iter().map(|key| key.to_term(env)).collect::<Vec<_>>();
    Term::map_from_term_arrays(env, &key_terms, values)
}


