    impl Node for SceneHandle {
        type Context = ();
        type ProcessingInstruction = SceneProcessingInstruction;
        type Document = SceneDocument;
        type Attribute = SceneAttribute;
        type Element = SceneElement;
        type Opaque = SceneHandleKind;
        fn is_comment(&self) -> bool {
            false
        }
        fn is_text(&self) -> bool {
            false
        }
        fn text_content(&self) -> String {
            match self.kind {
                SceneHandleKind::Document => String::new(),
                SceneHandleKind::Element(index) => {
                    self.scene.nodes[index].name.clone().unwrap_or_default()
                }
                SceneHandleKind::Attribute { owner, index } => {
                    self.scene
                        .nodes[owner]
                        .attr(index)
                        .map(|(_, value)| value)
                        .unwrap_or_default()
                }
            }
        }
        fn language(&self) -> Option<String> {
            None
        }
        fn parent(&self) -> Option<Self> {
            match self.kind {
                SceneHandleKind::Document => None,
                SceneHandleKind::Element(index) => {
                    self.scene
                        .nodes[index]
                        .parent
                        .map(|parent| Self::element(self.scene.clone(), parent))
                        .or_else(|| Some(Self::document(self.scene.clone())))
                }
                SceneHandleKind::Attribute { owner, .. } => {
                    Some(Self::element(self.scene.clone(), owner))
                }
            }
        }
        fn children(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            self.scene
                .children_of(&self.kind)
                .into_iter()
                .map(move |index| Self::element(scene.clone(), index))
        }
        fn compare_tree_order(&self, other: &Self) -> Ordering {
            fn rank(handle: &SceneHandle) -> usize {
                match handle.kind {
                    SceneHandleKind::Document => 0,
                    SceneHandleKind::Element(index) => handle.scene.ranks[index] + 1,
                    SceneHandleKind::Attribute { owner, index } => {
                        handle.scene.ranks[owner] + 1_000_000_000 + index
                    }
                }
            }
            rank(self).cmp(&rank(other))
        }
        fn traverse_preorder(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            let mut handles = Vec::new();
            if matches!(self.kind, SceneHandleKind::Document) {
                handles.push(Self::document(scene.clone()));
            }
            handles
                .extend(
                    self
                        .scene
                        .descendants_of(&self.kind)
                        .into_iter()
                        .map(move |index| Self::element(scene.clone(), index)),
                );
            handles.into_iter()
        }
        fn inclusive_ancestors(&self) -> impl Iterator<Item = Self> {
            let mut ancestors = Vec::new();
            let mut current = Some(self.clone());
            while let Some(node) = current {
                current = node.parent();
                ancestors.push(node);
            }
            ancestors.into_iter()
        }
        fn preceding_nodes(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            let ancestors = self
                .inclusive_ancestors()
                .filter_map(|node| node.element_index())
                .collect::<Vec<_>>();
            let cutoff = self
                .element_index()
                .map(|index| self.scene.ranks[index])
                .unwrap_or(0);
            let indexes = self
                .scene
                .preorder
                .iter()
                .copied()
                .take(cutoff)
                .filter(|index| !ancestors.contains(index))
                .collect::<Vec<_>>();
            indexes.into_iter().map(move |index| Self::element(scene.clone(), index))
        }
        fn following_nodes(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            let descendants = self.scene.descendants_of(&self.kind);
            let start = descendants
                .last()
                .map(|index| self.scene.ranks[*index] + 1)
                .unwrap_or(0);
            let indexes = self
                .scene
                .preorder
                .iter()
                .copied()
                .skip(start)
                .collect::<Vec<_>>();
            indexes.into_iter().map(move |index| Self::element(scene.clone(), index))
        }
        fn preceding_siblings(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            let indexes = self
                .element_index()
                .map(|index| self.scene.siblings_before(index))
                .unwrap_or_default();
            indexes.into_iter().map(move |index| Self::element(scene.clone(), index))
        }
        fn following_siblings(&self) -> impl Iterator<Item = Self> {
            let scene = self.scene.clone();
            let indexes = self
                .element_index()
                .map(|index| self.scene.siblings_after(index))
                .unwrap_or_default();
            indexes.into_iter().map(move |index| Self::element(scene.clone(), index))
        }
        fn owner_document(&self) -> Self::Document {
            SceneDocument(self.scene.clone())
        }
        fn to_opaque(&self) -> Self::Opaque {
            self.kind.clone()
        }
        fn as_processing_instruction(&self) -> Option<Self::ProcessingInstruction> {
            None
        }
        fn as_attribute(&self) -> Option<Self::Attribute> {
            matches!(self.kind, SceneHandleKind::Attribute { .. })
                .then(|| SceneAttribute(self.clone()))
        }
        fn as_element(&self) -> Option<Self::Element> {
            matches!(self.kind, SceneHandleKind::Element(_))
                .then(|| SceneElement(self.clone()))
        }
        fn get_root_node(&self) -> Self {
            Self::document(self.scene.clone())
        }
    }
    impl ProcessingInstruction for SceneProcessingInstruction {
        fn target(&self) -> String {
            String::new()
        }
    }
    impl Document for SceneDocument {
        type Node = SceneHandle;
        fn get_elements_with_id(
            &self,
            id: &str,
        ) -> impl Iterator<Item = <Self::Node as Node>::Element> {
            let scene = self.0.clone();
            let index = SceneGuid::parse(id)
                .and_then(|guid| scene.by_guid.get(&guid).copied());
            index
                .into_iter()
                .map(move |index| SceneElement(
                    SceneHandle::element(scene.clone(), index),
                ))
        }
    }
    impl Element for SceneElement {
        type Context = ();
        type Node = SceneHandle;
        type Attribute = SceneAttribute;
        fn as_node(&self) -> Self::Node {
            self.0.clone()
        }
        fn prefix(&self) -> Option<Prefix> {
            None
        }
        fn namespace(&self) -> Namespace {
            ns!()
        }
        fn local_name(&self) -> LocalName {
            let SceneHandleKind::Element(index) = self.0.kind else { unreachable!() };
            LocalName::from(self.0.scene.nodes[index].node_type)
        }
        fn attributes(&self, _cx: &mut ()) -> impl Iterator<Item = Self::Attribute> {
            let SceneHandleKind::Element(owner) = self.0.kind else { unreachable!() };
            let scene = self.0.scene.clone();
            let count = self.0.scene.nodes[owner].attr_count();
            (0..count)
                .map(move |index| SceneAttribute(
                    SceneHandle::attribute(scene.clone(), owner, index),
                ))
        }
        fn is_html_element_in_html_document(&self) -> bool {
            false
        }
    }
    impl Attribute for SceneAttribute {
        type Node = SceneHandle;
        fn as_node(&self) -> Self::Node {
            self.0.clone()
        }
        fn prefix(&self) -> Option<Prefix> {
            None
        }
        fn namespace(&self) -> Namespace {
            ns!()
        }
        fn local_name(&self) -> LocalName {
            let SceneHandleKind::Attribute { owner, index } = self.0.kind else {
                unreachable!()
            };
            LocalName::from(
                self.0.scene.nodes[owner].attr(index).map(|(name, _)| name).unwrap_or(""),
            )
        }
    }
    fn read_guid_value(decoder: &mut Decoder<'_>) -> NifResult<SceneGuid> {
        let session_id = decoder.read_var_uint()?;
        let local_id = decoder.read_var_uint()?;
        Ok(SceneGuid { session_id, local_id })
    }
    fn read_parent_index_value(
        decoder: &mut Decoder<'_>,
    ) -> NifResult<(SceneGuid, String)> {
        let guid = read_guid_value(decoder)?;
        let position = decoder.read_string_value()?;
        Ok((guid, position))
    }
    fn scene_node_record_optional_attr(
        record: &SceneNodeRecord,
        index: usize,
    ) -> Option<RecordAttribute> {
        let present = vec![
            record.name.is_some(), record.parent_guid.is_some(), record.position
            .is_some(), record.size.is_some(), record.size.is_some(), record.size
            .is_some(), record.size.is_some(), record.transform.is_some(), record.visible
            .is_some(), record.locked.is_some(), record.opacity.is_some(), record.text
            .is_some(), record.font_family.is_some(), record.font_style.is_some(), record
            .font_postscript.is_some(), record.font_size.is_some(), record
            .text_style_guid.is_some(), record.component_key.is_some(), record
            .origin_component_key.is_some(), record.fill_style_guid.is_some(), record
            .stroke_style_guid.is_some(), record.effect_style_guid.is_some(), record
            .grid_style_guid.is_some(), record.fill_count.is_some(), record.stroke_count
            .is_some()
        ];
        match present
            .into_iter()
            .enumerate()
            .map(|(index, item)| (item, index))
            .filter(|&(set, _field)| set)
            .nth(index)
        {
            Some((_set, field)) => {
                match field {
                    0 => record.name.as_ref().map(|value| ("name", value.clone())),
                    1 => {
                        record
                            .parent_guid
                            .as_ref()
                            .map(|value| ("parent_guid", value.to_string()))
                    }
                    2 => {
                        record.position.as_ref().map(|value| ("position", value.clone()))
                    }
                    3 => record.size.as_ref().map(|value| ("x", value.x.to_string())),
                    4 => record.size.as_ref().map(|value| ("y", value.y.to_string())),
                    5 => record.size.as_ref().map(|value| ("width", value.x.to_string())),
                    6 => {
                        record.size.as_ref().map(|value| ("height", value.y.to_string()))
                    }
                    7 => {
                        record
                            .transform
                            .as_ref()
                            .map(|value| (
                                "transform",
                                format!(
                                    "{},{},{},{},{},{}", value.m00, value.m01, value.m02, value
                                    .m10, value.m11, value.m12
                                ),
                            ))
                    }
                    8 => record.visible.map(|value| ("visible", value.to_string())),
                    9 => record.locked.map(|value| ("locked", value.to_string())),
                    10 => record.opacity.map(|value| ("opacity", value.to_string())),
                    11 => record.text.as_ref().map(|value| ("text", value.clone())),
                    12 => {
                        record
                            .font_family
                            .as_ref()
                            .map(|value| ("font_family", value.clone()))
                    }
                    13 => {
                        record
                            .font_style
                            .as_ref()
                            .map(|value| ("font_style", value.clone()))
                    }
                    14 => {
                        record
                            .font_postscript
                            .as_ref()
                            .map(|value| ("font_postscript", value.clone()))
                    }
                    15 => record.font_size.map(|value| ("font_size", value.to_string())),
                    16 => {
                        record
                            .text_style_guid
                            .as_ref()
                            .map(|value| ("text_style_guid", value.clone()))
                    }
                    17 => {
                        record
                            .component_key
                            .as_ref()
                            .map(|value| ("component_key", value.clone()))
                    }
                    18 => {
                        record
                            .origin_component_key
                            .as_ref()
                            .map(|value| ("origin_component_key", value.clone()))
                    }
                    19 => {
                        record
                            .fill_style_guid
                            .as_ref()
                            .map(|value| ("fill_style_guid", value.clone()))
                    }
                    20 => {
                        record
                            .stroke_style_guid
                            .as_ref()
                            .map(|value| ("stroke_style_guid", value.clone()))
                    }
                    21 => {
                        record
                            .effect_style_guid
                            .as_ref()
                            .map(|value| ("effect_style_guid", value.clone()))
                    }
                    22 => {
                        record
                            .grid_style_guid
                            .as_ref()
                            .map(|value| ("grid_style_guid", value.clone()))
                    }
                    23 => {
                        record.fill_count.map(|value| ("fill_count", value.to_string()))
                    }
                    24 => {
                        record
                            .stroke_count
                            .map(|value| ("stroke_count", value.to_string()))
                    }
                    _ => None,
                }
            }
            None => None,
        }
    }
    fn scene_node_record_optional_attr_count(record: &SceneNodeRecord) -> usize {
        let present = vec![
            record.name.is_some(), record.parent_guid.is_some(), record.position
            .is_some(), record.size.is_some(), record.size.is_some(), record.size
            .is_some(), record.size.is_some(), record.transform.is_some(), record.visible
            .is_some(), record.locked.is_some(), record.opacity.is_some(), record.text
            .is_some(), record.font_family.is_some(), record.font_style.is_some(), record
            .font_postscript.is_some(), record.font_size.is_some(), record
            .text_style_guid.is_some(), record.component_key.is_some(), record
            .origin_component_key.is_some(), record.fill_style_guid.is_some(), record
            .stroke_style_guid.is_some(), record.effect_style_guid.is_some(), record
            .grid_style_guid.is_some(), record.fill_count.is_some(), record.stroke_count
            .is_some()
        ];
        present.into_iter().filter(|&set| set).count()
    }
